inline uint64_t pack(const State&s){uint64_t x=0;for(int i=0;i<12;i++)x|=((uint64_t)s[i])<<(3*i);return x;} inline State unpack(uint64_t x){State s{};for(int i=0;i<12;i++)s[i]=(x>>(3*i))&7;return s;}
inline uint64_t tpack(const State&s,int a,int eps){State t{};for(int i=0;i<12;i++){int j=(eps*i+a)%12;if(j<0)j+=12;t[j]=s[i];}return pack(t);} unordered_map<uint64_t,uint64_t> CC; inline uint64_t canon(const State&s){uint64_t raw=pack(s);auto it=CC.find(raw);if(it!=CC.end())return it->second;uint64_t b=raw;for(int eps:{1,-1})for(int a=0;a<12;a++)b=min(b,tpack(s,a,eps));CC[raw]=b;return b;} inline uint64_t canonp(uint64_t p){return canon(unpack(p));}
inline int tot(uint64_t p){int z=0;for(int i=0;i<12;i++)z+=(p>>(3*i))&7;return z;} unordered_map<uint64_t,double> NC;
double normp(uint64_t p){auto it=NC.find(p);if(it!=NC.end())return it->second;State s=unpack(p);double z=0;for(int i=0;i<12;i++)for(int j=0;j<12;j++)z+=s[i]*G[i][j]*s[j];return NC[p]=z;}
